ed import instead of one example.","tree":{"sha":"484afad5a9a40b13d957f40ffedd58eefc03b660","url":"https://api.github.com/repos/native-federation/native-federation-core/git/trees/484afad5a9a40b13d957f40ffedd58eefc03b660"},"url":"https://api.github.com/repos/native-federation/native-federation-core/git/commits/d1ff673e34a8394b406da16619bf8b74971c55f5","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/11028826?v=4","events_url":"https://api.github.com/users/Aukevanoost/events{/privacy}","followers_url":"https://api.github.com/users/Aukevanoost/followers","following_url":"https://api.github.com/users/Aukevanoost/following{/other_user}","gists_url":"https://api.github.com/users/Aukevanoost/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/Aukevanoost","id":11028826,"login":"Aukevanoost","node_id":"MDQ6VXNlcjExMDI4ODI2","organizations_url":"https://api.github.com/users/Aukevanoost/orgs","received_events_url":"https://api.github.com/users/Aukevanoost/received_events","repos_url":"https://api.github.com/users/Aukevanoost/repos","site_admin":false,"starred_url":"https://api.github.com/users/Aukevanoost/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/Aukevanoost/subscriptions","type":"User","url":"https://api.github.com/users/Aukevanoost","user_view_type":"public"},"html_url":"https://github.com/native-federation/native-federation-core/commit/d1ff673e34a8394b406da16619bf8b74971c55f5","node_id":"C_kwDOQtD_rtoAKGQxZmY2NzNlMzRhODM5NGI0MDZkYTE2NjE5YmY4Yjc0OTcxYzU1ZjU","parents":[{"html_url":"https://github.com/native-federation/native-federation-core/commit/bc01158bda5483eb676ad432e559631172b9f9a5","sha":"bc01158bda5483eb676ad432e559631172b9f9a5","url":"https://api.github.com/repos/native-federation/native-federation-core/commits/bc01158bda5483eb676ad432e559631172b9f9a5"}],"sha":"d1ff673e34a8394b406da16619bf8b74971c55